l, "effective_from": null, "jurisdiction_scope": "national", "administrative_area_code": null, "quote_preview": "Phí, lệ phí Mô tả Trực tiếp 0 Miễn phí Các đơn vị quản lý ngành, lĩnh vực thuộc Bộ nộp Kế hoạch khảo sát chất lượng sản phẩm, hàng hóa hằng năm về Cục Đổi mới sáng tạo, Chuyển đổi xanh và Khuyến công thông qua hệ thống xử lý văn bản iMOIT/ cổng dịch vụ công trực tuyến hoặc trực...", "source_type": "government", "source_status": "snapshot", "crawled_at": "2026-07-17T17:45:53.8293289+07:00", "procedure_code": "5.003859", "snapshot_path": "pdf_thu_tuc/027_5.003859.pdf"}], "answer_strategy": "medium", "confidence_score": 0.65, "confidence_band": "medium", "confidence_reasons": ["snapshot_not_reviewed"], "external_search_used": false, "external_search_consent_required": false, "form_code": null, "translation_used": false}

